/*
 Problem: 1401. Circle and Rectangle Overlapping
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 7.8 MB (38.08%)
 Tags: Math, Geometry
*/
class Solution {
public:
    bool checkOverlap(int radius, int xCenter, int yCenter, int x1, int y1, int x2, int y2) {
        const auto closestX = max(x1, min(xCenter, x2));
        const auto closestY = max(y1, min(yCenter, y2));

        const auto dx = closestX - xCenter;
        const auto dy = closestY - yCenter;

        return dx * dx + dy * dy <= radius * radius;
    }
};
